package com.kuaixietech.aftersalesfunds;
import com.fasterxml.jackson.databind.*;
import com.kuaixietech.security.DomainAccessGuard;
import com.kuaixietech.service.finance.impl.AtomicMoneyService;
import jakarta.validation.constraints.*;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
@Service
public class AftersalesEscrowFunds {
 public record Execute(@NotBlank @Pattern(regexp="(?i)[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}") String requestId,@Min(1) int expectedRound,@NotBlank @Size(max=200) String note){}
 private final JdbcTemplate db;private final DomainAccessGuard guard;private final AtomicMoneyService money;private final EscrowFundsProof proof;private final ObjectMapper json;
 public AftersalesEscrowFunds(JdbcTemplate db,DomainAccessGuard guard,AtomicMoneyService money,EscrowFundsProof proof,ObjectMapper json){this.db=db;this.guard=guard;this.money=money;this.proof=proof;this.json=json;}
 private Map<String,Object> row(String sql,Object...args){return db.queryForList(sql,args).stream().findFirst().orElse(null);}
 private void changed(int count){if(count!=1)throw new IllegalStateException("AS_ESCROW_CONCURRENT_CHANGE");}
 private ResponseStatusException conflict(String code){return new ResponseStatusException(HttpStatus.CONFLICT,code);}
 private record CaseSource(Map<String,Object> order,Map<String,Object> dispute,Map<String,Object> after){}
 private CaseSource caseSource(String caseId,boolean lock){String suffix=lock?" FOR UPDATE":"";var id=row("SELECT order_id FROM t_disputes WHERE id=?",caseId);if(id==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"AS_ESCROW_CASE_UNAVAILABLE");var order=row("SELECT * FROM t_orders WHERE id=?"+suffix,id.get("order_id"));var dispute=row("SELECT * FROM t_disputes WHERE id=?"+suffix,caseId);var after=row("SELECT * FROM t_after_sales_cases WHERE id=? AND order_id=?"+suffix,caseId,id.get("order_id"));if(order==null||dispute==null||after==null)throw conflict("AS_ESCROW_CASE_NOT_PAYABLE");return new CaseSource(order,dispute,after);}
 private BigDecimal decision(CaseSource source,int expectedRound){var d=source.dispute();var after=source.after();if(((Number)d.get("round")).intValue()!=expectedRound)throw conflict("AS_ESCROW_CASE_CHANGED");if(!"awaiting_refund".equals(d.get("stage"))||!"awaiting_refund".equals(after.get("status"))||!"provider_unavailable".equals(after.get("refund_status"))||!Set.of("refund_part","refund_full","compensate").contains(d.get("verdict")))throw conflict("AS_ESCROW_CASE_NOT_PAYABLE");if(!"return_original".equals(d.get("deposit_owner")))throw conflict("AS_ESCROW_DEPOSIT_DECISION_REQUIRES_ACCOUNTING");if(!Objects.equals(source.order().get("buyer_id"),d.get("initiator_id"))||!Objects.equals(source.order().get("vendor_id"),d.get("respondent_id"))||!Objects.equals(source.order().get("buyer_id"),after.get("applicant_id")))throw conflict("AS_ESCROW_CASE_PARTIES_MISMATCH");BigDecimal amount=EscrowFundsProof.amount(d.get("refund_amount"));if(amount.signum()<=0||amount.compareTo(EscrowFundsProof.amount(after.get("refund_amount")))!=0)throw conflict("AS_ESCROW_DECISION_AMOUNT_MISMATCH");return amount;}
 @Transactional(readOnly=true) public Map<String,Object> budget(String caseId){guard.requireAdmin();var source=caseSource(caseId,false);var existing=row("SELECT * FROM t_order_escrow_refunds WHERE case_id=?",caseId);if(existing!=null){var result=view(existing);result.put("status","succeeded");return result;}var result=new LinkedHashMap<String,Object>();result.put("caseId",caseId);result.put("orderId",source.order().get("id"));result.put("currency","CNY");result.put("refundMethod","escrow_wallet");result.put("destination","platform_wallet");try{BigDecimal amount=decision(source,((Number)source.dispute().get("round")).intValue());var p=proof.prove(source.order().get("id").toString(),source.order(),false);if(amount.compareTo(p.remainingGoods())>0)throw conflict("AS_ESCROW_REFUND_CAP_EXCEEDED");result.put("status","eligible");result.put("goodsAmount",p.goods().toPlainString());result.put("alreadyRefunded",p.refunded().toPlainString());result.put("refundableGoods",p.remainingGoods().toPlainString());result.put("requestedAmount",amount.toPlainString());result.put("buyerEscrowHeld",p.held().toPlainString());result.put("serviceFeeHeld",p.fee().toPlainString());result.put("shippingHeld",p.shipping().toPlainString());result.put("requiresAccounting",amount.compareTo(p.remainingGoods())==0);result.put("sourceRound",source.dispute().get("round"));result.put("rewardReviewRequired",true);}catch(EscrowFundsProof.Blocked e){result.put("status","blocked");result.put("reasonCode",e.getMessage());}catch(ResponseStatusException e){result.put("status","blocked");result.put("reasonCode",e.getReason());}return result;}
 @Transactional public Map<String,Object> execute(String caseId,Execute input){String actor=guard.requireAdmin(),request=UUID.fromString(input.requestId()).toString();var source=caseSource(caseId,true);String orderId=source.order().get("id").toString(),hash=hash(caseId,input.expectedRound(),input.note().trim());var prior=row("SELECT * FROM t_order_escrow_refunds WHERE case_id=? FOR UPDATE",caseId);if(prior!=null){if(actor.equals(prior.get("operator_id"))&&request.equals(prior.get("request_id"))&&hash.equals(prior.get("request_hash")))return view(prior);throw conflict("AS_ESCROW_ALREADY_EXECUTED");}if(row("SELECT id FROM t_order_escrow_refunds WHERE operator_id=? AND request_id=? FOR UPDATE",actor,request)!=null)throw conflict("AS_ESCROW_REQUEST_REUSED");if(row("SELECT id FROM t_dispute_events WHERE dispute_id=? AND actor_id=? AND request_id=? FOR UPDATE",caseId,actor,request)!=null)throw conflict("AS_ESCROW_REQUEST_REUSED");BigDecimal amount=decision(source,input.expectedRound());var p=proof.prove(orderId,source.order(),true);if(amount.compareTo(p.remainingGoods())>0)throw conflict("AS_ESCROW_REFUND_CAP_EXCEEDED");boolean accounting=amount.compareTo(p.remainingGoods())==0;String id=UUID.nameUUIDFromBytes(("order-escrow-refund:"+actor+":"+request).getBytes(StandardCharsets.UTF_8)).toString();BigDecimal after=p.held().subtract(amount),refunded=p.refunded().add(amount);String note="售后货款退回；执行单 "+id;
  // The proof and all order/refund rows are locked before the wallet; no external payment or insurer is called.
  if(money.lockBalance(p.buyer())==null)throw new IllegalStateException("AS_ESCROW_WALLET_UNAVAILABLE");if(money.addBalance(p.buyer(),amount,EscrowFundsProof.LEDGER_KIND,orderId,note)==null)throw new IllegalStateException("AS_ESCROW_WALLET_UNAVAILABLE");var ledgerRows=db.queryForList("SELECT id,amount FROM t_balance_ledger WHERE user_id=? AND order_id=? AND kind=? AND note=? FOR UPDATE",p.buyer(),orderId,EscrowFundsProof.LEDGER_KIND,note);if(ledgerRows.size()!=1||EscrowFundsProof.amount(ledgerRows.getFirst().get("amount")).compareTo(amount)!=0)throw new IllegalStateException("AS_ESCROW_CREDIT_LEDGER_UNCONFIRMED");String walletLedger=ledgerRows.getFirst().get("id").toString();
  changed(db.update("UPDATE t_orders SET buyer_deposit=?,agreed_json=JSON_SET(agreed_json,'$.buyer_escrow',?,'$.goods_refunded',?),updated_at=CURRENT_TIMESTAMP(3) WHERE id=? AND buyer_deposit_status='frozen' AND buyer_deposit=? AND settled_at IS NULL",after,after,refunded,orderId,p.held()));changed(db.update("UPDATE t_deposits SET amount=?,updated_at=CURRENT_TIMESTAMP(3) WHERE id=? AND payer_id=? AND status='frozen' AND amount=?",after,p.buyerDeposit().get("id"),p.buyer(),p.held()));
  var snapshot=new LinkedHashMap<String,Object>();snapshot.put("pricingVersion",com.kuaixietech.service.trading.support.IntentPricing.EXTERNAL_VERSION);snapshot.put("productId",p.reservation().get("product_id"));snapshot.put("goods",p.goods());snapshot.put("serviceFee",p.fee());snapshot.put("shipping",p.shipping());snapshot.put("previousGoodsRefunds",p.refunded());snapshot.put("buyerEscrowBefore",p.held());snapshot.put("buyerEscrowAfter",after);snapshot.put("inventoryState","consumed");
  changed(db.update("INSERT INTO t_order_escrow_refunds(id,case_id,order_id,buyer_id,operator_id,request_id,request_hash,source_round,currency,amount,original_goods_amount,service_fee_held,shipping_held,buyer_escrow_before,buyer_escrow_after,source_deposit_id,wallet_ledger_id,requires_accounting,source_snapshot,note) VALUES(?,?,?,?,?,?,?,?,'CNY',?,?,?,?,?,?,?,?,?,CAST(? AS JSON),?)",id,caseId,orderId,p.buyer(),actor,request,hash,input.expectedRound(),amount,p.goods(),p.fee(),p.shipping(),p.held(),after,p.buyerDeposit().get("id"),walletLedger,accounting,encode(snapshot),input.note().trim()));String next=accounting?"awaiting_accounting":"resolved";
  changed(db.update("UPDATE t_after_sales_cases SET refund_status='succeeded',status=? WHERE id=? AND status='awaiting_refund' AND refund_status='provider_unavailable'",next,caseId));changed(db.update("UPDATE t_disputes SET stage=?,round=round+1,resolved_at=CASE WHEN ?='resolved' THEN CURRENT_TIMESTAMP(3) ELSE NULL END WHERE id=? AND stage='awaiting_refund' AND round=?",next,next,caseId,input.expectedRound()));
  changed(db.update("INSERT INTO t_order_escrow_refund_events(id,execution_id,actor_id,action,detail) VALUES(?,?,?,'wallet_refunded',?)",UUID.randomUUID().toString(),id,actor,"Actual platform-wallet credit from verified unspent goods escrow; no external-bank refund"));changed(db.update("INSERT INTO t_dispute_events(id,dispute_id,order_id,actor_id,actor_role,action,request_id,before_stage,after_stage,payload) VALUES(?,?,?,?,'operator','escrow_refunded',?,'awaiting_refund',?,CAST(? AS JSON))",UUID.randomUUID().toString(),caseId,orderId,actor,request,next,encode(Map.of("requestHash",hash,"input",Map.of("note",input.note().trim(),"refundMethod","escrow_wallet","amount",amount.toPlainString(),"executionId",id)))));
  changed(db.update("INSERT INTO t_notifications(id,user_id,kind,title,body,order_id) VALUES(?,?,'aftersales','售后货款已退至平台钱包',?,?)",UUID.randomUUID().toString(),p.buyer(),"货款 ¥"+amount.toPlainString()+" 已退入平台钱包；不是微信或银行卡退款。"+(accounting?"剩余费用及保证金待核对，订单继续暂停结算。":"后续按剩余货款结算；奖励及提成待核对。"),orderId));return view(Objects.requireNonNull(row("SELECT * FROM t_order_escrow_refunds WHERE id=?",id)));
 }
 /** Called by order settlement under the existing order lock, before any wallet mutation. */
 @Transactional public BigDecimal netGoods(String orderId,BigDecimal originalGoods){var order=row("SELECT * FROM t_orders WHERE id=? FOR UPDATE",orderId);var executions=db.queryForList("SELECT id FROM t_order_escrow_refunds WHERE order_id=? ORDER BY created_at,id FOR UPDATE",orderId);if(executions.isEmpty())return originalGoods;if(order==null||EscrowFundsProof.amount(order.get("goods_amount")).compareTo(originalGoods)!=0)throw new EscrowFundsProof.Blocked("AS_ESCROW_SETTLEMENT_GROSS_MISMATCH");return proof.prove(orderId,order,true).remainingGoods();}
 public List<Map<String,Object>> mine(int limit,int offset){String user=guard.requireActiveProfile();page(limit,offset);return db.queryForList("SELECT * FROM t_order_escrow_refunds WHERE buyer_id=? ORDER BY created_at DESC,id DESC LIMIT ? OFFSET ?",user,limit,offset).stream().map(AftersalesEscrowFunds::view).toList();}
 public List<Map<String,Object>> events(String id,boolean admin,int limit,int offset){String actor=admin?guard.requireAdmin():guard.requireActiveProfile();page(limit,offset);var execution=row("SELECT buyer_id FROM t_order_escrow_refunds WHERE id=?",id);if(execution==null||!admin&&!actor.equals(execution.get("buyer_id")))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"AS_ESCROW_EXECUTION_UNAVAILABLE");return db.queryForList("SELECT id,action,detail,created_at AS createdAt FROM t_order_escrow_refund_events WHERE execution_id=? ORDER BY created_at DESC,id DESC LIMIT ? OFFSET ?",id,limit,offset).stream().map(e->{var v=new LinkedHashMap<String,Object>(e);v.put("createdAt",time(e.get("createdAt")));return (Map<String,Object>)v;}).toList();}
 public Map<String,Object> forCase(String caseId){var execution=row("SELECT * FROM t_order_escrow_refunds WHERE case_id=?",caseId);return execution==null?null:view(execution);}
 private void page(int limit,int offset){if(limit<1||limit>100||offset<0)throw new IllegalArgumentException("AS_ESCROW_INVALID_PAGE");}
 private String hash(String caseId,int round,String note){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(encode(Map.of("caseId",caseId,"expectedRound",round,"note",note)).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException("AS_ESCROW_REQUEST_HASH_FAILED");}}
 private String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalArgumentException("AS_ESCROW_INVALID_JSON");}}
 static String time(Object value){if(value==null)return null;if(value instanceof java.sql.Timestamp t)return t.toInstant().toString();if(value instanceof java.time.LocalDateTime t)return t.toInstant(java.time.ZoneOffset.UTC).toString();return value.toString();}
 static Map<String,Object> view(Map<String,Object> r){var v=new LinkedHashMap<String,Object>();v.put("id",r.get("id"));v.put("caseId",r.get("case_id"));v.put("orderId",r.get("order_id"));v.put("requestId",r.get("request_id"));v.put("sourceRound",r.get("source_round"));v.put("amount",EscrowFundsProof.amount(r.get("amount")).toPlainString());v.put("currency","CNY");v.put("status","succeeded");v.put("refundMethod","escrow_wallet");v.put("destination","platform_wallet");v.put("requiresAccounting",EscrowFundsProof.truth(r.get("requires_accounting")));v.put("rewardReviewRequired",true);v.put("createdAt",time(r.get("created_at")));return v;}
}
